// BFS function to count nodes
int bfs(Node *root)
{
    int cnt = 0;

    // Create queue and push root
    queue<Node *> pq;
    pq.push(root);

    while (!pq.empty())
    {
        // Remove front node and increment count
        Node *node = pq.front();
        pq.pop();

        cnt += 1;

        // Add left child
        if (node->left)
        {
            pq.push(node->left);
        }

        // Add right child
        if (node->right)
        {
            pq.push(node->right);
        }
    }

    return cnt;
}

