#define N 100000
// Define Node structure
struct Node
{
    int data;
    struct Node *left;
    struct Node *right;
};

// Function to create a new node
struct Node *createNode(int x)
{
    struct Node *newNode = (struct Node *)malloc(sizeof(struct Node));
    newNode->data = x;
    newNode->left = NULL;
    newNode->right = NULL;
    return newNode;
}

// Simple queue implementation using array
struct Node *queue[N];
int front = 0, rear = 0;

// Enqueue operation
void enqueue(struct Node *node)
{
    queue[rear++] = node;
}

// Dequeue operation
struct Node *dequeue()
{
    return queue[front++];
}

// Check if queue is empty
int isEmpty()
{
    return front == rear;
}

// BFS function to count nodes
int bfs(struct Node *root)
{
    int cnt = 0;

    // Push root node into queue
    enqueue(root);

    while (!isEmpty())
    {
        // Remove front node and increment count
        struct Node *node = dequeue();
        cnt++;

        // Add left child
        if (node->left)
            enqueue(node->left);

        // Add right child
        if (node->right)
            enqueue(node->right);
    }

    return cnt;
}

// Function to get size of tree
int getSize(struct Node *root)
{
    if (root == NULL)
        return 0;
    return bfs(root);
}

